import json, hashlib, pathlib
out = pathlib.Path("/home/vgpnk/Projects/shokunin/kama-shokunin/.ufo/waves/round-28/w1/out/DataG11")
doc = json.loads((out/"rows.json").read_text())
def canon(v): return json.dumps(v, sort_keys=True, ensure_ascii=False)
def is_num(v): return isinstance(v,(int,float)) and not isinstance(v,bool)
def same(a,b):
    if is_num(a) and is_num(b):
        return abs(a-b) <= 1e-6*max(1.0,abs(a),abs(b))
    return canon(a)==canon(b)
base = json.loads((out/"resp_base.json").read_bytes())
r = doc["rows"][0]
live = json.loads((out/"resp_lora_dup.json").read_bytes())
sha = hashlib.sha256((out/"resp_lora_dup.json").read_bytes()).hexdigest()
gs = live["generation_settings"]["lora"]
sent, val = r["set"]["lora"], r["outcome"]["value"]
print("sha_match", sha == r["live"]["response_sha256"])
print("live_gs", gs, "same_as_row_value", same(gs, val))
print("identity?", same(val, sent), "default?", same(val, base["generation_settings"]["lora"]))
print("meaning_words", len(r["meaning"].split()))
print("quote_words", len(r["source"]["quote"].split()))
# every cited sha exists among the stored bodies
cited = {r["live"]["response_sha256"]}
for nr in doc["no_rows"]:
    cited.add(nr["live"]["response_sha256"])
    cited.add(nr["live"].get("unknown_field_control_sha256"))
    for p in nr["live"].get("probes", []): cited.add(p["response_sha256"])
    if "echo_probe" in nr["live"]: cited.add(nr["live"]["echo_probe"]["response_sha256"])
have = {hashlib.sha256(p.read_bytes()).hexdigest(): p.name for p in out.glob("resp_*.json")}
print("all_cited_present", cited <= set(have), "missing", cited - set(have))
print({s: have[s] for s in cited if s in have})
# no_row key checks
for nr in doc["no_rows"]:
    body = json.loads((out/have[nr["live"]["response_sha256"]]).read_bytes())
    gs2 = body.get("generation_settings")
    print(nr["field"], "status", nr["live"]["status"], "gs_present", gs2 is not None, "error", (body.get("error") or {}).get("message") if isinstance(body.get("error"),dict) else None)

